	className?: string;
	size?: "default" | "sm";
}) {
	return (
		<BaseSwitch.Root
			data-slot="switch"
			data-size={size}
			className={cn(
				"group/switch border-border focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive/60 aria-invalid:ring-destructive/30 data-checked:border-primary data-checked:bg-primary data-unchecked:bg-muted dark:aria-invalid:ring-destructive/40 aria-invalid:data-checked:border-primary ease-out-quint relative inline-flex shrink-0 items-center rounded-full border transition-[background-color,border-color,box-shadow] duration-200 outline-none after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:ring-3 aria-invalid:ring-3 data-disabled:cursor-not-allowed data-disabled:opacity-50 data-[size=default]:h-4.5 data-[size=default]:w-8 data-[size=sm]:h-3.5 data-[size=sm]:w-6 any-pointer-coarse:after:inset-y-[calc(50%-22px)] any-pointer-coarse:data-[size=default]:h-5.5 any-pointer-coarse:data-[size=default]:w-10 any-pointer-coarse:data-[size=sm]:h-4.5 any-pointer-coarse:data-[size=sm]:w-8",
				className,
			)}
			{...props}
		>
			<BaseSwitch.Thumb
				data-slot="switch-thumb"
				className="bg-background dark:data-checked:bg-primary-foreground dark:data-unchecked:bg-foreground ease-out-quint pointer-events-none block origin-left rounded-[50%] shadow-[0_1px_2px_--theme(--color-black/12%)] transition-[translate,scale,border-radius,transform-origin,background-color] duration-200 group-data-[size=default]/switch:size-4 group-data-[size=sm]/switch:size-3 data-checked:origin-right data-checked:translate-x-[calc(100%-2px)] motion-safe:not-data-disabled:group-active/switch:scale-x-115 motion-safe:not-data-disabled:group-active/switch:rounded-[43.5%/50%] motion-safe:not-data-disabled:group-has-[+input+label:active]/switch:scale-x-115 motion-safe:not-data-disabled:group-has-[+input+label:active]/switch:rounded-[43.5%/50%] motion-safe:not-data-disabled:in-[label:active]:scale-x-115 motion-safe:not-data-disabled:in-[label:active]:rounded-[43.5%/50%] motion-reduce:transition-[background-color] rtl:origin-right rtl:data-checked:origin-left rtl:data-checked:-translate-x-[calc(100%-2px)] any-pointer-coarse:group-data-[size=default]/switch:size-5 any-pointer-coarse:group-data-[size=sm]/switch:size-4 motion-safe:not-data-disabled:[label:active+[data-slot=switch]_&]:scale-x-115 motion-safe:not-data-disabled:[label:active+[data-slot=switch]_&]:rounded-[43.5%/50%]"
			/>
